(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025-t*0.4)*8 + Math.cos(sy*0.02+t*0.3)*6;
  const w2y = Math.cos(sy*0.022+t*0.35)*8 + Math.sin(sx*0.028-t*0.45)*6;
  const wx = sx + w2x, wy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.5],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.75],
    [60+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.5+2)*40, 0.14, 1.3, 0.85],
    [420+Math.cos(t*0.45+1)*50, 200+Math.sin(t*0.65+4)*50, 0.11, 2.1, 0.65]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((wx-sX)**2 + (wy-sY)**2);
    aS += w*Math.sin(d*f - t*sp);
    iS += w*Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    cS += w*Math.cos(d*f*0.5 - t*sp*0.4 + 3.0);
  }
  const n = src.length, act = aS/n, inh = iS/n, cor = cS/n;
  const bg = (Math.sin(wx*0.04+wy*0.025+t*0.8)+Math.sin(wx*0.03-wy*0.04+t*1.1))/2 + Math.sin((wx+wy)*0.12+t*2.5)*0.2 + Math.sin((wx-wy)*0.1-t*2)*0.2 + Math.sin(wx*0.08+t*0.5)*Math.sin(wy*0.06-t*0.7)*0.15;
  const dist = Math.sqrt((wx-cx)**2+(wy-cy)**2), ang = Math.atan2(wy-cx, wx-cy);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*5+t*0.8)*0.5)*0.25;
  const cellX = (wx*0.15)|0, cellY = (wy*0.15)|0;
  const cellDx = wx*0.15-cellX-0.5, cellDy = wy*0.15-cellY-0.5;
  const cellDist = Math.sqrt(cellDx**2+cellDy**2);
  const cell = Math.tanh((Math.sin(cellX*1.3+t*0.5)*Math.sin(cellY*1.7-t*0.3)+Math.sin((cellX+cellY)*0.8+t)*0.5)*1.5)*0.3;
  const edgeFade = 1.0-Math.exp(-cellDist*8)*0.4;
  const fine = Math.sin(wx*0.2+wy*0.15+t*1.5)*Math.cos(wx*0.18-wy*0.22-t*1.2)*0.3;
  const reaction = Math.tanh((act-inh*0.6+cor*0.3+bg*0.25+spiral*0.3+fine)*2.0);
  const blend = reaction*0.7+cell*0.2+fine*0.1, v = blend*0.5+0.5;
  const pal = [[5,12,52],[12,45,85],[18,85,115],[25,135,130],[60,165,120],[140,185,80],[210,195,60],[225,155,55],[215,105,60],[185,65,55],[140,40,60],[85,22,65],[40,15,58],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const glow = Math.abs(reaction)>0.75?1.12:1.0;
  const br = lum*glow*edgeFade;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*br)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*br)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*br)|0
  ];
}
